package com.archos.mediacenter.video.player;

import android.app.*;
import android.view.*;
import android.widget.*;
import com.archos.mediacenter.video.leanback.*;
import com.archos.mediacenter.video.utils.OpenSubtitlesSearchResult;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(application=Application.class,sdk=28,qualifiers="w960dp-h540dp-land-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PlaybackSubtitlePanelTest {
    private org.robolectric.android.controller.ActivityController<PreviewPlaybackMenusTest.TopNavigationTestHost> host;private Dialog main;private PlaybackSubtitlePanel panel;private Model model;
    static final class Model implements PlaybackSubtitlePanel.Backend {
        final Map<String,Integer> values=new HashMap<>(Map.of("enabled",1,"size",50,"colour",android.graphics.Color.WHITE,"position",128,"outline",1,"background",1,"opacity",128,"delay",0));int selected=0,downloads,trackCount=15;public boolean available(){return true;}public int get(String key){return values.get(key);}public void set(String key,int value){values.put(key,value);}public void download(){downloads++;}
        public List<PlaybackSubtitlePanel.Track> tracks(){List<PlaybackSubtitlePanel.Track> out=new ArrayList<>();for(int i=0;i<trackCount;i++){final int n=i;out.add(new PlaybackSubtitlePanel.Track(i==0?"English (SDH)":"Track "+i,i==0?"en-GB":i==1?"en-US":"fr",selected==i,true,()->selected=n));}return out;}
    }
    @Before public void setup(){host=Robolectric.buildActivity(PreviewPlaybackMenusTest.TopNavigationTestHost.class).setup().visible();model=new Model();panel=new PlaybackSubtitlePanel(host.get(),model,i->{});main=new Dialog(host.get());main.setContentView(panel);main.show();main.getWindow().setBackgroundDrawableResource(android.R.color.transparent);main.getWindow().setLayout(panel.panelWidth(),panel.panelHeight());layout(main);panel.focusTab();}
    @After public void close(){panel.close();main.dismiss();host.pause().stop().destroy();}
    private void layout(Dialog dialog){View decor=dialog.getWindow().getDecorView();for(int n=0;n<3;n++){decor.measure(View.MeasureSpec.makeMeasureSpec(dialog.getWindow().getAttributes().width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(dialog.getWindow().getAttributes().height,View.MeasureSpec.EXACTLY));decor.layout(0,0,decor.getMeasuredWidth(),decor.getMeasuredHeight());Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}}
    private View row(String key){return panel.findViewWithTag("subtitles.row."+key);}
    private void key(View row,int code){assertTrue(row.requestFocus());row.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,code));row.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,code));}
    @Test public void mainHasExactTenRowsInOrderAndCapturesApprovedLayout()throws Exception{String[] keys={"enabled","track","download","size","colour","position","outline","background","opacity","delay"};int previous=-1;for(String key:keys){View v=row(key);assertNotNull(key,v);assertTrue(v.getTop()>previous);previous=v.getTop();assertTrue(v.isFocusable());}key(panel.findViewWithTag("playback.tab:1"),KeyEvent.KEYCODE_DPAD_DOWN);assertTrue(row("enabled").hasFocus());key(row("enabled"),KeyEvent.KEYCODE_DPAD_UP);assertTrue(panel.findViewWithTag("playback.tab:1").hasFocus());capture(main,"subtitles-main-1920x1080");}
    @Test public void everyInlineControlUsesRealValuesAndApproved100msDelay(){row("enabled").performClick();assertEquals(0,model.get("enabled"));row("enabled").performClick();key(row("size"),KeyEvent.KEYCODE_DPAD_RIGHT);assertEquals(75,model.get("size"));key(row("size"),KeyEvent.KEYCODE_DPAD_LEFT);assertEquals(50,model.get("size"));key(row("colour"),KeyEvent.KEYCODE_DPAD_RIGHT);assertEquals(PlaybackSubtitlePanel.COLOURS[1],model.get("colour"));key(row("position"),KeyEvent.KEYCODE_DPAD_RIGHT);assertEquals(255,model.get("position"));row("outline").performClick();assertEquals(0,model.get("outline"));row("background").performClick();assertEquals(0,model.get("background"));key(row("opacity"),KeyEvent.KEYCODE_DPAD_RIGHT);assertEquals(191,model.get("opacity"));key(row("delay"),KeyEvent.KEYCODE_DPAD_LEFT);assertEquals(-100,model.get("delay"));key(row("delay"),KeyEvent.KEYCODE_DPAD_RIGHT);assertEquals(0,model.get("delay"));row("download").performClick();assertEquals(1,model.downloads);}
    @Test public void openingPreservesCustomValuesAndRefreshKeepsFocusedRow(){model.values.put("size",63);model.values.put("position",43);model.values.put("opacity",95);row("size").requestFocus();panel.refresh();assertEquals(63,model.get("size"));assertEquals(43,model.get("position"));assertEquals(95,model.get("opacity"));assertTrue(row("size").hasFocus());}
    @Test public void tracksScrollSelectAndBackRestoreWithoutFabricatedChoices()throws Exception{row("track").requestFocus();row("track").performClick();Dialog popup=org.robolectric.shadows.ShadowDialog.getLatestDialog();layout(popup);View first=popup.getWindow().getDecorView().findViewWithTag("subtitles.track.0");assertTrue(first.hasFocus());ViewGroup second=popup.getWindow().getDecorView().findViewWithTag("subtitles.track.1");second.requestFocus();second.performClick();assertEquals(1,model.selected);assertEquals(View.VISIBLE,second.getChildAt(second.getChildCount()-1).getVisibility());View last=popup.getWindow().getDecorView().findViewWithTag("subtitles.track.14");last.requestFocus();layout(popup);android.graphics.Rect bounds=new android.graphics.Rect();assertTrue(last.getGlobalVisibleRect(bounds));assertEquals(last.getHeight(),bounds.height());first.requestFocus();layout(popup);capture(popup,"subtitles-track-1920x1080");assertTrue(panel.dismissPopup());assertTrue(row("track").hasFocus());}
    @Test public void trackReenumerationKeepsThePopupAndUsesOnlyCurrentTracks(){row("track").performClick();Dialog popup=org.robolectric.shadows.ShadowDialog.getLatestDialog();layout(popup);View first=popup.getWindow().getDecorView().findViewWithTag("subtitles.track.0");first.requestFocus();model.trackCount=3;model.selected=2;panel.refresh();layout(popup);assertTrue(popup.isShowing());assertNull(popup.getWindow().getDecorView().findViewWithTag("subtitles.track.3"));ViewGroup selected=popup.getWindow().getDecorView().findViewWithTag("subtitles.track.2");assertEquals(View.VISIBLE,selected.getChildAt(selected.getChildCount()-1).getVisibility());assertTrue(popup.getWindow().getDecorView().findViewWithTag("subtitles.track.0").hasFocus());}
    @Test public void downloadRendersRealProviderDataEllipsisFlagsAndIndependentSearch()throws Exception{List<OpenSubtitlesSearchResult> results=new ArrayList<>();for(int i=0;i<12;i++){OpenSubtitlesSearchResult r=new OpenSubtitlesSearchResult("fixture"+i,i==0?"Dune.Part.Two.2024.English.SDH.with.a.long.provider.filename.for.ellipsis.srt":"Provider result "+i,"en-GB");r.setHearingImpaired(i==0);results.add(r);}Dialog popup=SubtitleResultsPanel.show(host.get(),results,r->{});layout(popup);ViewGroup row=popup.getWindow().getDecorView().findViewWithTag("subtitles.result.0");assertTrue(row.hasFocus());LinearLayout copy=(LinearLayout)row.getChildAt(2);TextView filename=(TextView)copy.getChildAt(0);assertEquals(1,filename.getLineCount());assertNotNull(filename.getEllipsize());assertTrue(((TextView)copy.getChildAt(1)).getText().toString().contains("Size unavailable"));capture(popup,"subtitles-download-1920x1080");popup.dismiss();}
    private void capture(Dialog dialog,String name)throws Exception{View v=dialog.getWindow().getDecorView();android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(v.getWidth(),v.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(bitmap));java.io.File file=new java.io.File("build/reports/subtitles-ui/"+name+".png");file.getParentFile().mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}
}
